ALTER TABLE public.store_settings ADD COLUMN scheduling_enabled boolean NOT NULL DEFAULT false, ADD COLUMN delivery_zones_enabled boolean NOT NULL DEFAULT false, ADD COLUMN free_delivery_minimum numeric NOT NULL DEFAULT 0 CHECK (free_delivery_minimum>=0), ADD COLUMN demand_mode text NOT NULL DEFAULT 'auto' CHECK (demand_mode IN ('auto','normal','busy','overload')), ADD COLUMN club_enabled boolean NOT NULL DEFAULT false, ADD COLUMN auto_print_enabled boolean NOT NULL DEFAULT false, ADD COLUMN paper_width integer NOT NULL DEFAULT 80 CHECK (paper_width IN (58,80));
ALTER TABLE public.orders ADD COLUMN scheduled_at timestamptz, ADD COLUMN delivery_fee numeric NOT NULL DEFAULT 0, ADD COLUMN delivery_zone text NOT NULL DEFAULT '', ADD COLUMN review_token uuid NOT NULL DEFAULT gen_random_uuid(), ADD COLUMN club_member_id uuid, ADD COLUMN club_credits_used integer NOT NULL DEFAULT 0, ADD COLUMN vip boolean NOT NULL DEFAULT false;
CREATE TABLE public.delivery_zones (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, fee numeric NOT NULL CHECK(fee>=0), active boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.delivery_zones TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.delivery_zones TO authenticated; GRANT ALL ON public.delivery_zones TO service_role;
ALTER TABLE public.delivery_zones ENABLE ROW LEVEL SECURITY;
CREATE POLICY zones_public ON public.delivery_zones FOR SELECT TO anon,authenticated USING(active OR public.has_role(auth.uid(),'admin'));
CREATE POLICY zones_admin ON public.delivery_zones FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.order_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL UNIQUE REFERENCES public.orders(id), dough integer NOT NULL CHECK(dough BETWEEN 1 AND 5), temperature integer NOT NULL CHECK(temperature BETWEEN 1 AND 5), flavor integer NOT NULL CHECK(flavor BETWEEN 1 AND 5), message text NOT NULL DEFAULT '' CHECK(length(message)<=1000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.order_reviews TO authenticated; GRANT ALL ON public.order_reviews TO service_role;
ALTER TABLE public.order_reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY reviews_directors ON public.order_reviews FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.club_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, monthly_price numeric NOT NULL CHECK(monthly_price>0), pizza_quota integer NOT NULL CHECK(pizza_quota BETWEEN 1 AND 30), eligible_product_ids uuid[] NOT NULL DEFAULT '{}', free_delivery boolean NOT NULL DEFAULT false, priority boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.club_plans TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.club_plans TO authenticated; GRANT ALL ON public.club_plans TO service_role;
ALTER TABLE public.club_plans ENABLE ROW LEVEL SECURITY;
CREATE POLICY plans_public ON public.club_plans FOR SELECT TO anon,authenticated USING(active OR public.has_role(auth.uid(),'admin'));
CREATE POLICY plans_admin ON public.club_plans FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.club_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, plan_id uuid NOT NULL REFERENCES public.club_plans(id), phone text NOT NULL, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','cancelled','pending')), monthly_price numeric NOT NULL, credits integer NOT NULL CHECK(credits>=0), period_start timestamptz NOT NULL DEFAULT now(), period_end timestamptz NOT NULL DEFAULT (now()+interval '1 month'), redemption_token uuid NOT NULL DEFAULT gen_random_uuid(), is_demo boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_active_membership ON public.club_members(user_id) WHERE status='active';
GRANT SELECT ON public.club_members TO authenticated; GRANT ALL ON public.club_members TO service_role;
ALTER TABLE public.club_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY members_read ON public.club_members FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.club_contract (id integer PRIMARY KEY DEFAULT 1 CHECK(id=1), billing_mode text NOT NULL DEFAULT 'per_subscriber' CHECK(billing_mode IN ('per_subscriber','monthly')), percentage numeric NOT NULL DEFAULT 5 CHECK(percentage BETWEEN 0 AND 100), monthly_fee numeric NOT NULL DEFAULT 0 CHECK(monthly_fee>=0), agreed boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.club_contract TO authenticated; GRANT ALL ON public.club_contract TO service_role;
ALTER TABLE public.club_contract ENABLE ROW LEVEL SECURITY;
CREATE POLICY contract_read ON public.club_contract FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.platform_operators (user_id uuid PRIMARY KEY);
GRANT SELECT ON public.platform_operators TO authenticated; GRANT ALL ON public.platform_operators TO service_role;
ALTER TABLE public.platform_operators ENABLE ROW LEVEL SECURITY;
CREATE POLICY operator_self ON public.platform_operators FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.print_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL UNIQUE REFERENCES public.orders(id), state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','printing','printed','failed')), device_id uuid, claimed_at timestamptz, printed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.print_jobs TO authenticated; GRANT ALL ON public.print_jobs TO service_role;
ALTER TABLE public.print_jobs ENABLE ROW LEVEL SECURITY;
CREATE POLICY print_read ON public.print_jobs FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'staff'));
CREATE FUNCTION public.enqueue_print() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT NEW.is_demo AND (SELECT auto_print_enabled FROM public.store_settings WHERE id=1) THEN INSERT INTO public.print_jobs(order_id) VALUES(NEW.id) ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER order_print_queue AFTER INSERT ON public.orders FOR EACH ROW EXECUTE FUNCTION public.enqueue_print();
CREATE FUNCTION public.claim_print(_device uuid) RETURNS SETOF public.print_jobs LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'staff')) THEN RAISE EXCEPTION 'Forbidden'; END IF; RETURN QUERY UPDATE public.print_jobs SET state='printing',device_id=_device,claimed_at=now() WHERE id=(SELECT j.id FROM public.print_jobs j JOIN public.orders o ON o.id=j.order_id WHERE j.state='pending' AND (o.scheduled_at IS NULL OR o.scheduled_at<=now()+interval '35 minutes') AND o.status NOT IN ('cancelado','entregue') AND (SELECT auto_print_enabled FROM public.store_settings WHERE id=1) ORDER BY j.created_at FOR UPDATE OF j SKIP LOCKED LIMIT 1) RETURNING *; END $$;
REVOKE ALL ON FUNCTION public.claim_print(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.claim_print(uuid) TO authenticated;
CREATE FUNCTION public.finish_print(_job uuid,_device uuid,_success boolean) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'staff')) THEN RAISE EXCEPTION 'Forbidden'; END IF; UPDATE public.print_jobs SET state=CASE WHEN _success THEN 'printed' ELSE 'failed' END,printed_at=CASE WHEN _success THEN now() ELSE NULL END WHERE id=_job AND device_id=_device AND state='printing'; RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.finish_print(uuid,uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.finish_print(uuid,uuid,boolean) TO authenticated;
CREATE FUNCTION public.demand_count() RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT count(*)::integer FROM public.orders WHERE status IN ('recebido','preparando') AND (scheduled_at IS NULL OR scheduled_at<=now()+interval '35 minutes') AND NOT is_demo $$;
REVOKE ALL ON FUNCTION public.demand_count() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.demand_count() TO anon,authenticated,service_role;
CREATE FUNCTION public.submit_review(_order uuid,_token uuid,_dough integer,_temperature integer,_flavor integer,_message text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r uuid; BEGIN IF NOT EXISTS(SELECT 1 FROM public.orders WHERE id=_order AND review_token=_token AND status='entregue') THEN RAISE EXCEPTION 'Pedido não elegível para avaliação'; END IF; INSERT INTO public.order_reviews(order_id,dough,temperature,flavor,message) VALUES(_order,_dough,_temperature,_flavor,_message) RETURNING id INTO r; RETURN r; END $$;
REVOKE ALL ON FUNCTION public.submit_review(uuid,uuid,integer,integer,integer,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.submit_review(uuid,uuid,integer,integer,integer,text) TO service_role;
CREATE FUNCTION public.insert_club_order(_order jsonb,_member uuid,_token uuid,_credits integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.club_members; result uuid; BEGIN SELECT * INTO m FROM public.club_members WHERE id=_member AND redemption_token=_token AND status='active' AND period_end>now() FOR UPDATE; IF NOT FOUND OR m.credits<_credits OR _credits<0 THEN RAISE EXCEPTION 'Saldo do clube indisponível'; END IF; INSERT INTO public.orders(customer_name,phone,address,delivery_method,items,total,discount,is_demo,points_earned,points_redeemed,table_id,people,scheduled_at,delivery_fee,delivery_zone,club_member_id,club_credits_used,vip) VALUES(_order->>'customer_name',_order->>'phone',_order->>'address',_order->>'delivery_method',_order->'items',(_order->>'total')::numeric,(_order->>'discount')::numeric,(_order->>'is_demo')::boolean,(_order->>'points_earned')::integer,(_order->>'points_redeemed')::integer,(_order->>'table_id')::uuid,(_order->>'people')::integer,(_order->>'scheduled_at')::timestamptz,(_order->>'delivery_fee')::numeric,_order->>'delivery_zone',_member,_credits,(_order->>'vip')::boolean) RETURNING id INTO result; UPDATE public.club_members SET credits=credits-_credits WHERE id=m.id; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.insert_club_order(jsonb,uuid,uuid,integer) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.insert_club_order(jsonb,uuid,uuid,integer) TO service_role;